/* Находим атом с номером 45 (atom_id формата ...-45-...) */
WITH target_atom AS (
    SELECT "atom_id"
    FROM "atom"
    WHERE (SUBSTR("atom_id", 7, 2))::int = 45
)
/* Получаем связи, в которых участвует этот атом, и их типы */
SELECT b."bond_type", b."bond_id"
FROM "bond" b
JOIN "connected" c ON c."bond_id" = b."bond_id"
JOIN target_atom ta ON ta."atom_id" = c."atom_id" OR ta."atom_id" = c."atom_id2";
```

