```sql
/* Общее количество карт */
WITH total AS (
    SELECT COUNT(id) AS total_count
    FROM cards
),
/* Карты Story Spotlight без текстового блока */
spotlight_textless AS (
    SELECT id
    FROM cards
    WHERE isstoryspotlight = 1
      AND istextless = 1
),
/* Количество таких карт */
spotlight_count AS (
    SELECT COUNT(id) AS cnt
    FROM spotlight_textless
)
/* Процент и список ID */
SELECT
    (SELECT cnt FROM spotlight_count)::numeric
        / NULLIF((SELECT total_count FROM total), 0) * 100 AS percentage,
    (SELECT array_agg(id ORDER BY id) FROM spotlight_textless) AS card_ids;
```

