/* Доля карт без силы (power IS NULL или '*'), которые при этом на французском языке */
SELECT
    /* Числитель: карты без power на французском; знаменатель: все карты без power */
    COUNT(CASE WHEN c."language" = 'French' THEN 1 END) * 100.0
        / NULLIF(COUNT(*), 0) AS percentage
FROM "cards" c
WHERE c."power" IS NULL OR c."power" = '*';
```

