```sql
/* Процент пользователей с 0 upvotes среди авторов комментариев со score от 5 до 10 */
SELECT
    /* Числитель: уникальные пользователи с upvotes = 0 */
    COUNT(DISTINCT CASE WHEN u."upvotes" = 0 THEN c."userid" END) * 100.0
    / NULLIF(COUNT(DISTINCT c."userid"), 0) AS percentage
FROM "comments" c
JOIN "users" u ON u."id" = c."userid"
WHERE c."score" BETWEEN 5 AND 10;
```

