```sql
/* Полные имена героев, у которых более 15 суперспособностей */
SELECT s."full_name"
FROM "superhero" AS s
JOIN (
    /* Считаем количество способностей для каждого героя и фильтруем > 15 */
    SELECT hp."hero_id"
    FROM "hero_power" AS hp
    GROUP BY hp."hero_id"
    HAVING COUNT(hp."power_id") > 15
) AS p ON s."id" = p."hero_id";
```

