/* Процент "good" супергероев среди всех супергероев Marvel Comics */
SELECT
    /* Доля героев с alignment = 'Good' среди героев Marvel, в процентах */
    SUM(CASE WHEN a."alignment" = 'Good' THEN 1 ELSE 0 END) * 100.0 / COUNT(*) AS good_percentage
FROM "superhero" s
JOIN "publisher" p ON s."publisher_id" = p."id"
LEFT JOIN "alignment" a ON s."alignment_id" = a."id"
WHERE p."publisher_name" = 'Marvel Comics';
```

