/* Вычисляем процент LAM-клиентов, потребивших более 46.73 */
SELECT
    /* Числитель: LAM-клиенты с потреблением > 46.73 */
    (COUNT(DISTINCT CASE WHEN ym."consumption" > 46.73 THEN c."customerid" END)::numeric
     /
     /* Знаменатель: все LAM-клиенты */
     NULLIF(COUNT(DISTINCT c."customerid"), 0)
    ) * 100 AS "percent_lam_consumed_over_46_73"
FROM "customers" c
LEFT JOIN "yearmonth" ym
    ON ym."customerid" = c."customerid"
WHERE c."segment" = 'LAM';
```
